const sp = all.filter((v) => v.views >= ABS_HI);   // 채널은 따지지 않는다
const fp = all.filter((v) => v.views <= ABS_LO);
const auc = pairs(S, F);   // 성공 하나, 실패 하나를 짝지어 비교

const REL_HI = 3, REL_LO = 0.5;
sp = all.filter((v) => v.views >= ABS_HI && v.views >= REL_HI * med[v.c]);
fp = all.filter((v) => hasWinner[v.c] && v.views <= REL_LO * med[v.c]);

const CAP = 2;
const cnt = {};
sp = sp.filter((v) => (cnt[v.c] = (cnt[v.c] || 0) + 1) <= CAP);
const boot = Array.from({ length: 200 }, () => auc(resample(sp, 30), resample(fp, 12)));
